var UNITS = [{"n": 1, "title": "Serviço B2B x B2C, crédito do tomador e comparação por regime", "cvar": "u1", "lessons": [{"id": "K1", "type": "teoria", "title": "Quem toma o serviço define quem aproveita o crédito", "xp": 10, "data": "V1"}, {"id": "K2", "type": "drill", "title": "Praticar · B2B x B2C e crédito do tomador", "xp": 25, "data": ["S1", "S2", "S3", "S4", "T0", "T1", "T2"]}, {"id": "K3", "type": "flash", "title": "Flashcards · B2B x B2C e crédito do tomador", "xp": 15, "data": [0, 1, 2, 3, 4]}]}, {"n": 2, "title": "Consultoria e contabilidade: o caso do escritório e o crédito do cliente", "cvar": "u2", "lessons": [{"id": "K4", "type": "teoria", "title": "Escritório (presumido ou Simples) servindo cliente lucro real", "xp": 10, "data": "V2"}, {"id": "K5", "type": "drill", "title": "Praticar · escritório de contabilidade e consultoria", "xp": 25, "data": ["S5", "S6", "S7", "S8", "S9", "T3", "T4", "T5", "T6"]}, {"id": "K6", "type": "flash", "title": "Flashcards · escritório de contabilidade e consultoria", "xp": 15, "data": [5, 6, 7, 8, 9, 10]}]}, {"n": 3, "title": "Saúde, educação e transporte coletivo: redução de 60%", "cvar": "u3", "lessons": [{"id": "K7", "type": "teoria", "title": "Serviços com redução de 60% da alíquota", "xp": 10, "data": "V3"}, {"id": "K8", "type": "drill", "title": "Praticar · saúde, educação e transporte", "xp": 25, "data": ["S10", "S11", "S12", "S13", "T7", "T8", "T9", "T10"]}, {"id": "K9", "type": "flash", "title": "Flashcards · saúde, educação e transporte", "xp": 15, "data": [11, 12, 13, 14, 15]}]}, {"n": 4, "title": "Construção civil, incorporação, venda e locação de imóveis", "cvar": "u4", "lessons": [{"id": "K10", "type": "teoria", "title": "Imóveis: redução de 50%/70%, redutor de ajuste e redutor social", "xp": 10, "data": "V4"}, {"id": "K11", "type": "drill", "title": "Praticar · construção e imóveis", "xp": 25, "data": ["S14", "S15", "S16", "S17", "S18", "T11", "T12", "T13", "T14"]}, {"id": "K12", "type": "flash", "title": "Flashcards · construção e imóveis", "xp": 15, "data": [16, 17, 18, 19, 20, 21]}]}, {"n": 5, "title": "Serviços financeiros, planos de saúde, plataformas e administração pública", "cvar": "u5", "lessons": [{"id": "K13", "type": "teoria", "title": "Regimes específicos e responsabilidade de plataformas", "xp": 10, "data": "V5"}, {"id": "K14", "type": "drill", "title": "Praticar · financeiros, planos, plataformas e setor público", "xp": 25, "data": ["S19", "S20", "S21", "S22", "T15", "T16", "T17", "T18"]}, {"id": "K15", "type": "flash", "title": "Flashcards · financeiros, planos, plataformas e setor público", "xp": 15, "data": [22, 23, 24, 25, 26]}]}, {"n": 6, "title": "Franquia, marketing e publicidade, locação de bens móveis", "cvar": "u1", "lessons": [{"id": "K16", "type": "teoria", "title": "Royalties, agências e locações: crédito e base de cálculo", "xp": 10, "data": "V6"}, {"id": "K17", "type": "drill", "title": "Praticar · franquia, marketing e locação", "xp": 25, "data": ["S23", "S24", "S25", "S26", "T19", "T20", "T21", "T22"]}, {"id": "K18", "type": "flash", "title": "Flashcards · franquia, marketing e locação", "xp": 15, "data": [27, 28, 29, 30, 31]}]}, {"n": 7, "title": "ISS na transição (2026 a 2033) com exemplo numérico", "cvar": "u2", "lessons": [{"id": "K19", "type": "teoria", "title": "ISS caindo e IBS/CBS subindo", "xp": 10, "data": "V7"}, {"id": "K20", "type": "drill", "title": "Praticar · transição do ISS", "xp": 25, "data": ["S27", "S28", "S29", "S30", "T23", "T24", "T25", "T26"]}, {"id": "K21", "type": "flash", "title": "Flashcards · transição do ISS", "xp": 15, "data": [32, 33, 34, 35, 36]}]}, {"n": 8, "title": "Fixação", "cvar": "u1", "lessons": [{"id": "Krev", "type": "review", "title": "Revisão geral do módulo", "xp": 60, "data": null}, {"id": "K22", "type": "missao", "title": "Missão TEC Concursos", "xp": 15, "data": null}, {"id": "K23", "type": "prova", "title": "Simulado cronometrado", "xp": 100, "data": null}]}];
var COM = {"0": "<p>Certo. No B2C não há quem credite; o tributo é suportado pelo consumidor.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "1": "<p>Errado. Por padrão o Simples apura IBS/CBS por dentro do DAS; o crédito integral decorre do regime regular.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "2": "<p>Errado. Salários não geram crédito: só aquisições tributadas de bens e serviços do regime regular.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "3": "<p>Certo. Menos tributo destacado, menos crédito: o custo líquido do cliente regular fica neutro.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "4": "<p>Certo. O prestador é regular e destaca o tributo; o cliente regular credita.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "5": "<p>Errado. A redução é proporcional: 26,5% x 0,70 = 18,55%.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "6": "<p>Certo. Por isso a redução de 30% o beneficia diretamente no preço final.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "7": "<p>Certo. Com 26,5% hipotéticos, a alíquota efetiva é 10,6%.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "8": "<p>Errado. Entradas com 26,5% e saídas com 10,6% podem gerar crédito maior que o débito.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "9": "<p>Certo. Nota da tabela da RFB: o 8% exige sociedade empresária que atenda às normas da Anvisa.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "10": "<p>Errado. A lei complementar define quais operações são beneficiadas.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "11": "<p>Certo. Art. 260 da LC 214/2025, na redação da LC 227/2026.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "12": "<p>Errado. O redutor é só para uso residencial; a base comercial é o valor integral.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "13": "<p>Certo. Sem contribuinte regular não há débito nem crédito.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "14": "<p>Errado. Art. 252, § 5º-A, I: não será constituído redutor para o não contribuinte.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "15": "<p>Certo. Art. 22 da LC 214/2025; há exceções (confira).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "16": "<p>Errado. Têm regime específico (art. 182 e seguintes) com base e alíquotas próprias.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "17": "<p>Certo. Arts. 194 a 197 da LC 214/2025, na redação dada pela LC 227/2026.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "18": "<p>Certo. Texto do art. 233, I; confira a versão vigente.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "19": "<p>Certo. 7.950 nos dois casos no exemplo: 26,5% sobre 30.000.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "20": "<p>Errado. Sem regime regular, não há crédito pela alíquota cheia.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "21": "<p>Certo. Desde que o serviço seja usado na atividade do franqueado.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "22": "<p>Errado. O redutor social é específico da locação de bem imóvel residencial.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "23": "<p>Certo. Art. 128 e art. 129 do ADCT, na redação da EC 132.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "24": "<p>Errado. O crédito é só de IBS/CBS.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "25": "<p>Certo. Art. 125 do ADCT, § 1º.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "26": "<p>Errado. Em 2033 o ISS é extinto; só IBS e CBS.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>"};
